size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, QuantumType quantum_type, unsigned char *compact_pixels, MagickOffsetType size_offset, MagickBooleanType separate) {
  size_t bytes_written = 0;
  ssize_t y;
  unsigned char *pixels = NULL;
  size_t length = 0;
  MagickBooleanType status = MagickTrue;

  if (image == (Image *) NULL)
    return 0;

  if (image->columns == 0 || image->rows == 0)
    return 0;

  pixels = (unsigned char *) AcquireMemory(image->columns * 4);
  if (pixels == (unsigned char *) NULL) {
    ThrowBinaryException(ResourceLimitError, "UnableToAcquireMemory", image->filename);
    return 0;
  }

  for (y = 0; y < (ssize_t) image->rows; y++) {
    if (ExportImagePixels(image, 0, y, image->columns, 1, "RGBO", pixels) != MagickTrue) {
      status = MagickFalse;
      break;
    }

    if (psd_info->compression == RLECompression) {
      length = CompressRLE(pixels, image->columns, compact_pixels + bytes_written);
      if (length == 0) {
        status = MagickFalse;
        break;
      }
    } else {
      (void) memcpy(compact_pixels + bytes_written, pixels, image->columns * 4);
      length = image->columns * 4;
    }

    bytes_written += length;
  }

  if (status == MagickTrue) {
    if (WriteBlobMemory(image, bytes_written, compact_pixels) != MagickTrue) {
      status = MagickFalse;
    }
  }

  if (pixels != (unsigned char *) NULL) {
    pixels = (unsigned char *) RelinquishMemory(pixels);
  }

  if (status == MagickFalse) {
    bytes_written = 0;
  }

  return bytes_written;
}
